class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ["homework", "quiz"]:
            raise ValueError("Invalid assignment kind. Must be 'homework' or 'quiz'.")
        if weight < 0:
            raise ValueError("Assignment weight cannot be negative.")
        self.assignments[name] = {"weight": weight, "kind": kind}
        if name not in self.grades:
            self.grades[name] = {}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self.assignments:
            raise ValueError("Assignment not found.")
        if not 2.0 <= grade <= 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0.")
        if student not in self.grades[assignment]:
            self.grades[assignment][student] = []
        self.grades[assignment][student].append(grade)

    def average(self, student: str) -> float:
        total_weight = sum(assignment["weight"] for assignment in self.assignments.values())
        total_score = 0
        for assignment, details in self.assignments.items():
            if student in self.grades[assignment]:
                if details["kind"] == "quiz" and len(self.grades[assignment][student]) > 1:
                    grade = min(self.grades[assignment][student])
                else:
                    if len(self.grades[assignment][student]) > 1:
                        raise ValueError("Multiple grades for a single homework assignment.")
                    grade = self.grades[assignment][student][0]
            else:
                grade = 2.0
            total_score += details["weight"] * grade
        return round(total_score / total_weight, 2)

    def students(self) -> list[str]:
        """Returns all students with at least one grade, sorted."""
        students = set()
        for assignment in self.grades.values():
            students.update(assignment.keys())
        return sorted(list(students))

    def grades(self, student: str) -> dict[str, float]:
        """Returns the student's recorded grades."""
        student_grades = {}
        for assignment, grades in self.grades.items():
            if student in grades:
                if self.assignments[assignment]["kind"] == "quiz" and len(grades[student]) > 1:
                    student_grades[assignment] = min(grades[student])
                else:
                    if len(grades[student]) > 1:
                        raise ValueError("Multiple grades for a single homework assignment.")
                    student_grades[assignment] = grades[student][0]
        return student_grades

    def remove_assignment(self, name: str) -> None:
        if name not in self.assignments:
            raise ValueError("Assignment not found.")
        del self.assignments[name]
        if name in self.grades:
            del self.grades[name]
```

